# Workflow graph (entry module) — generated by graphical-agents from the Graph IR (critic_loop_workflow).

from langgraph.graph import END, START, StateGraph

try:
    from .loops import code_loop
except ImportError:
    from loops import code_loop
try:
    from .state import WorkflowState
except ImportError:
    from state import WorkflowState

builder = StateGraph(WorkflowState)
builder.add_node("code_loop", code_loop)

builder.add_edge(START, "code_loop")
builder.add_edge("code_loop", END)

graph = builder.compile()
